const upsertCatalogPending = `-- name: UpsertCatalogPending :exec
INSERT INTO catalog_pending_courses (group_key, school, major, subject_name, subject_code, request_count, first_at, last_at)
VALUES (?, ?, ?, ?, ?, 0, ?, ?)
ON DUPLICATE KEY UPDATE last_at = VALUES(last_at), major = IF(major = '', VALUES(major), major)
`

type UpsertCatalogPendingParams struct {
	GroupKey    string
	School      string
	Major       string
	SubjectName string
	SubjectCode sql.NullString
	Now         time.Time
}

func (q *Queries) UpsertCatalogPending(ctx context.Context, arg UpsertCatalogPendingParams) error {
	_, err := q.db.ExecContext(ctx, upsertCatalogPending,
		arg.GroupKey,
		arg.School,
		arg.Major,
		arg.SubjectName,
		arg.SubjectCode,
		arg.Now,
		arg.Now,
	)
	return err
}

const usersOfCatalogCourse = `-- name: UsersOfCatalogCourse :many
SELECT DISTINCT owner_user_id FROM subjects WHERE catalog_course_id = ?
`

// 官方题库上线时通知在 1.1 选了该课的用户。
func (q *Queries) UsersOfCatalogCourse(ctx context.Context, catalogCourseID sql.NullInt64) ([]uint64, error) {
	rows, err := q.db.QueryContext(ctx, usersOfCatalogCourse, catalogCourseID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uint64{}
	for rows.Next() {
		var owner_user_id uint64
		if err := rows.Scan(&owner_user_id); err != nil {
			return nil, err
		}
		items = append(items, owner_user_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
